begin;
alter table public.accounts drop constraint accounts_kind_check;
alter table public.accounts add constraint accounts_kind_check check(kind in('wallet','savings','treasury','escrow','business','issuance'));
alter table public.accounts drop constraint accounts_balance_check;
alter table public.accounts add constraint accounts_balance_check check(balance>=0 or kind='issuance');
create unique index system_account_kind on public.accounts(kind) where kind in('issuance','treasury');
insert into public.accounts(kind) values('issuance'),('treasury');
alter table public.transactions add column effective_at timestamptz not null default now();
create table public.economy_rates(id uuid primary key default gen_random_uuid(),effective_date date not null unique,daily_basis_points integer not null check(daily_basis_points between 0 and 100),daily_account_cap bigint not null check(daily_account_cap between 0 and 10000000),created_by uuid references public.profiles,created_at timestamptz not null default now());
insert into public.economy_rates(effective_date,daily_basis_points,daily_account_cap) values((now() at time zone 'Europe/Moscow')::date,30,100000);
create table public.interest_accruals(account_id uuid references public.accounts,period date not null,opening_balance bigint not null,rate_id uuid not null references public.economy_rates,amount bigint not null check(amount>=0),transaction_id uuid unique references public.transactions,created_at timestamptz not null default now(),primary key(account_id,period));
create table public.subscription_plans(code text primary key,name text not null,price bigint not null check(price>0),days integer not null check(days between 1 and 366),listing_limit integer not null check(listing_limit between 1 and 1000),job_limit integer not null check(job_limit between 1 and 20),benefits text[] not null,active boolean not null default true);
insert into public.subscription_plans values('plus','Kapani Plus',50000,30,10,2,array['До 10 объявлений','До 2 работ'],true),('ultra','Kapani Ultra',150000,30,30,3,array['До 30 объявлений','До 3 работ'],true),('prime','Kapani Prime',300000,30,100,5,array['До 100 объявлений','До 5 работ'],true);
create table public.user_subscriptions(user_id uuid primary key references public.profiles,plan_code text not null references public.subscription_plans,expires_at timestamptz not null,updated_at timestamptz not null default now());
create table public.subscription_purchases(id uuid primary key default gen_random_uuid(),payer_id uuid not null references public.profiles,recipient_id uuid not null references public.profiles,plan_code text not null references public.subscription_plans,price bigint not null,days integer not null,transaction_id uuid not null references public.transactions,idempotency_key uuid not null,created_at timestamptz not null default now(),unique(payer_id,idempotency_key));
do $$declare t text;begin foreach t in array array['economy_rates','interest_accruals','subscription_plans','user_subscriptions','subscription_purchases'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end $$;
create policy rates_read on public.economy_rates for select to authenticated using(kapani_private.active());
create policy interest_read on public.interest_accruals for select to authenticated using(exists(select 1 from public.accounts where id=account_id and owner_id=auth.uid()));
create policy plans_read on public.subscription_plans for select to authenticated using(kapani_private.active());
create policy subscriptions_read on public.user_subscriptions for select to authenticated using(kapani_private.active() and user_id=auth.uid());
create policy purchases_read on public.subscription_purchases for select to authenticated using(kapani_private.active() and (payer_id=auth.uid() or recipient_id=auth.uid()));
create trigger immutable_interest before update or delete on public.interest_accruals for each row execute function kapani_private.immutable();
create trigger immutable_rates before update or delete on public.economy_rates for each row execute function kapani_private.immutable();
create trigger immutable_subscription_purchase before update or delete on public.subscription_purchases for each row execute function kapani_private.immutable();
create function kapani_private.issue(p_account uuid,p_amount bigint,p_actor uuid,p_kind text,p_effective timestamptz) returns uuid language plpgsql security definer set search_path='' as $$declare issuer uuid;tx uuid;begin
 if p_amount<=0 or p_amount>100000000 or p_amount is null then raise exception 'Emission limit';end if;
 select id into issuer from public.accounts where kind='issuance';
 perform 1 from public.accounts where id in(issuer,p_account) order by id for update;
 if p_account=issuer or not exists(select 1 from public.accounts where id=p_account) then raise exception 'Invalid account';end if;
 insert into public.transactions(actor,idempotency_key,kind,effective_at) values(p_actor,gen_random_uuid(),p_kind,p_effective) returning id into tx;
 insert into public.entries(transaction_id,account_id,amount) values(tx,issuer,-p_amount),(tx,p_account,p_amount);
 update public.accounts set balance=balance-p_amount where id=issuer;update public.accounts set balance=balance+p_amount where id=p_account;return tx;
end $$;
revoke all on function kapani_private.issue(uuid,bigint,uuid,text,timestamptz) from public,anon,authenticated;
create function public.municipal_grant(p_user uuid,p_amount bigint,p_key uuid,p_reason text) returns uuid language plpgsql security definer set search_path='' as $$declare tx uuid;w uuid;begin
 if not kapani_private.mayor() or p_user=auth.uid() then raise exception 'Access denied';end if;
 if p_key is null or p_reason is null or length(trim(p_reason))<10 then raise exception 'Reason required';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key::text,4));
 select entity into tx from public.audit_log where actor=auth.uid() and action='municipal_grant' and details->>'key'=p_key::text;
 if tx is not null then if not exists(select 1 from public.audit_log where entity=tx and details->>'user'=p_user::text and details->>'amount'=p_amount::text and details->>'reason'=p_reason) then raise exception 'Idempotency conflict';end if;return tx;end if;
 if not exists(select 1 from public.profiles where id=p_user and verified and not blocked) then raise exception 'Recipient not verified';end if;
 select id into w from public.accounts where owner_id=p_user and kind='wallet';tx:=kapani_private.issue(w,p_amount,auth.uid(),'municipal_grant',now());
 insert into public.audit_log(actor,action,entity,details) values(auth.uid(),'municipal_grant',tx,jsonb_build_object('key',p_key,'user',p_user,'amount',p_amount,'reason',p_reason));
 insert into public.notifications(user_id,category,title,body,href) values(p_user,'finance','Муниципальное начисление',p_reason,'#bank');return tx;
end $$;
create function kapani_private.accrue_interest(p_day date) returns integer language plpgsql security definer set search_path='' as $$declare a record;r public.economy_rates;opening bigint;amount bigint;tx uuid;cutoff timestamptz;n integer:=0;begin
 if p_day is null or p_day>=(now() at time zone 'Europe/Moscow')::date then raise exception 'Period not closed';end if;
 perform pg_advisory_xact_lock(hashtextextended('kapani_interest_'||p_day::text,5));
 select * into r from public.economy_rates where effective_date<=p_day order by effective_date desc limit 1;if r.id is null then return 0;end if;
 cutoff:=(p_day+1)::timestamp at time zone 'Europe/Moscow';
 for a in select * from public.accounts where kind='savings' and created_at<cutoff order by id loop
 if exists(select 1 from public.interest_accruals where account_id=a.id and period=p_day) then continue;end if;
 select coalesce(sum(e.amount),0) into opening from public.entries e join public.transactions t on t.id=e.transaction_id where e.account_id=a.id and t.effective_at<cutoff;
 amount:=least(r.daily_account_cap,greatest(0,floor(opening::numeric*r.daily_basis_points/10000)::bigint));tx:=null;
 if amount>0 then tx:=kapani_private.issue(a.id,amount,a.owner_id,'savings_interest',cutoff);
 insert into public.notifications(user_id,category,title,href) values(a.owner_id,'finance','Начислен доход по накоплениям','#bank');end if;
 insert into public.interest_accruals(account_id,period,opening_balance,rate_id,amount,transaction_id) values(a.id,p_day,opening,r.id,amount,tx);n:=n+1;
 end loop;return n;
end $$;
revoke all on function kapani_private.accrue_interest(date) from public,anon,authenticated;
create function kapani_private.daily_jobs() returns void language plpgsql security definer set search_path='' as $$declare d date;start_day date;end_day date;begin
 perform pg_advisory_xact_lock(hashtextextended('kapani_daily_jobs',6));
 end_day:=(now() at time zone 'Europe/Moscow')::date-1;
 select min(effective_date) into start_day from public.economy_rates;
 if start_day is null then return;end if;
 for d in select x::date from generate_series(start_day::timestamp,end_day::timestamp,interval '1 day')x loop perform kapani_private.accrue_interest(d);end loop;
end $$;
revoke all on function kapani_private.daily_jobs() from public,anon,authenticated;
create function public.buy_subscription(p_plan text,p_recipient uuid,p_key uuid) returns uuid language plpgsql security definer set search_path='' as $$declare p public.subscription_plans;s public.user_subscriptions;prev public.subscription_purchases;wallet uuid;treasury uuid;tx uuid;purchase uuid;begin
 if not kapani_private.active() or not exists(select 1 from public.profiles where id=auth.uid() and verified) then raise exception 'Municipal verification required';end if;
 if p_key is null or not exists(select 1 from public.profiles where id=p_recipient and not blocked) then raise exception 'Invalid recipient';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_key::text,7));
 select * into prev from public.subscription_purchases where payer_id=auth.uid() and idempotency_key=p_key;
 if prev.id is not null then if prev.plan_code<>p_plan or prev.recipient_id<>p_recipient then raise exception 'Idempotency conflict';end if;return prev.id;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_recipient::text,8));
 select * into p from public.subscription_plans where code=p_plan and active;
 if p.code is null then raise exception 'Plan unavailable';end if;
 select * into s from public.user_subscriptions where user_id=p_recipient for update;
 if s.expires_at>now() and s.plan_code<>p_plan then raise exception 'Wait for current plan expiry';end if;
 select id into wallet from public.accounts where owner_id=auth.uid() and kind='wallet';select id into treasury from public.accounts where kind='treasury';
 tx:=kapani_private.move_money(wallet,treasury,p.price,auth.uid(),'subscription_purchase');
 insert into public.user_subscriptions(user_id,plan_code,expires_at) values(p_recipient,p.code,greatest(coalesce(s.expires_at,now()),now())+make_interval(days=>p.days)) on conflict(user_id) do update set plan_code=excluded.plan_code,expires_at=excluded.expires_at,updated_at=now();
 insert into public.subscription_purchases(payer_id,recipient_id,plan_code,price,days,transaction_id,idempotency_key) values(auth.uid(),p_recipient,p.code,p.price,p.days,tx,p_key) returning id into purchase;
 insert into public.notifications(user_id,category,title,href) values(p_recipient,'subscription','Подписка активирована','#subscriptions');return purchase;
end $$;
create function kapani_private.listing_limit() returns trigger language plpgsql security definer set search_path='' as $$declare lim integer:=3;begin
 if not new.active then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.seller_id::text,9));
 select coalesce((select p.listing_limit from public.user_subscriptions s join public.subscription_plans p on p.code=s.plan_code where s.user_id=new.seller_id and s.expires_at>now()),3) into lim;
 if (select count(*) from public.listings where seller_id=new.seller_id and active and id<>new.id)>=lim then raise exception 'Listing limit reached';end if;return new;
end $$;
revoke all on function kapani_private.listing_limit() from public,anon,authenticated;
create trigger enforce_listing_limit before insert or update of active on public.listings for each row execute function kapani_private.listing_limit();
create function kapani_private.job_limit() returns trigger language plpgsql security definer set search_path='' as $$declare lim integer;begin
 if new.status<>'accepted' or old.status='accepted' then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.applicant_id::text,10));
 select coalesce((select p.job_limit from public.user_subscriptions s join public.subscription_plans p on p.code=s.plan_code where s.user_id=new.applicant_id and s.expires_at>now()),1) into lim;
 if(select count(*) from public.job_applications where applicant_id=new.applicant_id and status='accepted' and id<>new.id)>=lim then raise exception 'Job limit reached';end if;return new;
end $$;
revoke all on function kapani_private.job_limit() from public,anon,authenticated;
create trigger enforce_job_limit before update of status on public.job_applications for each row execute function kapani_private.job_limit();
revoke all on function public.municipal_grant(uuid,bigint,uuid,text),public.buy_subscription(text,uuid,uuid) from public,anon;
grant execute on function public.municipal_grant(uuid,bigint,uuid,text),public.buy_subscription(text,uuid,uuid) to authenticated;
commit;
